def checkout(db, request_id, quantity):
    if (not isinstance(request_id, str) or not request_id or
            len(request_id) > 64 or
            any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-' for c in request_id) or
            type(quantity) is not int or not 1 <= quantity <= 5):
        return 400, {'error': 'Invalid purchase request'}
    db.execute('BEGIN IMMEDIATE')
    try:
        stock, price = db.execute('SELECT stock, unit_price_cents FROM inventory WHERE id=1').fetchone()
        if quantity > stock:
            db.rollback()
            return 409, {'error': 'Insufficient stock'}
        # Legacy defect: retries are treated as new purchases.
        cursor = db.execute('INSERT INTO orders(request_id,quantity,total_cents) VALUES(?,?,?)',
                            (request_id, quantity, quantity * price))
        db.execute('UPDATE inventory SET stock=stock-? WHERE id=1', (quantity,))
        db.commit()
        return 201, {'orderId': cursor.lastrowid, 'requestId': request_id,
                     'quantity': quantity, 'totalCents': quantity * price}
    except Exception:
        db.rollback()
        raise
